<script lang="ts">
  import { enhance } from '$app/forms';
  import { page } from '$app/state';
  import { Users, UserPlus, ArrowRight, Github, KeyRound, Copy, Check, ShieldCheck, AlertCircle, LogOut } from 'lucide-svelte';
  import type { PageData, ActionData } from './$types';
  let { data, form }: { data: PageData; form: ActionData } = $props();
  let copied = $state(false);
  let base = $derived(`/challenges/${data.config.slug}`);
  async function copyCode() {
    if (!data.team) return;
    await navigator.clipboard.writeText(data.team.inviteCode);
    copied = true;
    window.setTimeout(() => copied = false, 2000);
  }
</script>

<div class="page-heading"><div><p class="eyebrow">WORKSPACE / PARTICIPATION</p><h1>My team</h1><p class="page-intro">Collaborate on predictions and manage your challenge membership.</p></div><span class="badge badge-neutral"><Users size={14} aria-hidden="true" />Up to {data.config.teamSizeLimit} members</span></div>
{#if form?.message}<div class="alert" class:alert-error={page.status >= 400} class:alert-success={page.status < 400} role="status">{#if page.status >= 400}<AlertCircle size={17} aria-hidden="true" />{:else}<Check size={17} aria-hidden="true" />{/if}{form.message}</div>{/if}
{#if !data.user}<div class="panel prerequisite-panel"><span class="empty-icon"><Github size={29} aria-hidden="true" /></span><div><h2>Sign in to join a team</h2><p>Your team membership and submissions are linked to your account.</p></div><a class="button button-primary" href="/login">Sign in <ArrowRight size={16} aria-hidden="true" /></a></div>{:else if data.team}<section class="panel team-overview"><div class="team-header"><span class="large-team-avatar">{data.team.name.slice(0, 1).toUpperCase()}</span><div><p class="eyebrow">YOUR CHALLENGE TEAM</p><h2>{data.team.name}</h2><span class="muted">{data.team.members.length} member{data.team.members.length === 1 ? '' : 's'} · {data.config.title}</span></div><a class="button button-primary" href={`${base}/submit`}>Submit predictions <ArrowRight size={16} aria-hidden="true" /></a></div><div class="invite-panel"><div><KeyRound size={20} aria-hidden="true" /><span><strong>Invite a teammate</strong><small>Share this code privately. Anyone with the code can join your team.</small></span></div><div class="invite-code"><code>{data.team.inviteCode}</code><button class="icon-button" type="button" aria-label="Copy invitation code" onclick={copyCode}>{#if copied}<Check size={17} aria-hidden="true" />{:else}<Copy size={17} aria-hidden="true" />{/if}</button></div></div><div class="panel-heading"><Users size={18} aria-hidden="true" /><h3>Team members</h3></div><div class="members-list">{#each data.team.members as member}<div class="member-row"><span class="team-avatar">{member.name.slice(0, 1).toUpperCase()}</span><span class="member-details"><strong>{member.name}</strong><small>{member.email}</small></span><span class="badge badge-neutral">{member.role === 'owner' ? 'Team owner' : 'Member'}</span></div>{/each}</div><div class="team-footer">{#if data.team.role === 'owner'}<span class="field-help"><ShieldCheck size={16} aria-hidden="true" />Team owners retain membership to preserve submissions and team access.</span>{:else}<span class="field-help">Leaving removes access to this team’s private submission history.</span><form method="POST" action="?/leave" use:enhance><button class="button button-danger" type="submit"><LogOut size={15} aria-hidden="true" />Leave team</button></form>{/if}</div></section>{:else}<div class="team-form-grid"><section class="panel team-form"><span class="form-heading-icon"><Users size={27} aria-hidden="true" /></span><h2>Create a team</h2><p>Start a new team. You can work alone or invite collaborators after registration.</p><form method="POST" action="?/create" use:enhance><label for="team-name">Team name</label><input id="team-name" name="name" placeholder="e.g. Sequence Lab" maxlength="60" minlength="2" required autocomplete="off" /><p class="field-help">Choose a unique name. It will appear on the public leaderboard.</p><button class="button button-primary" type="submit">Create team <ArrowRight size={16} aria-hidden="true" /></button></form></section><section class="panel team-form"><span class="form-heading-icon"><UserPlus size={27} aria-hidden="true" /></span><h2>Join an existing team</h2><p>Have an invitation? Enter the code shared by a teammate to join their team.</p><form method="POST" action="?/join" use:enhance><label for="invite-code">Invitation code</label><input id="invite-code" name="inviteCode" placeholder="Enter your invitation code" required autocomplete="off" /><p class="field-help">You can belong to one team per challenge.</p><button class="button button-secondary" type="submit">Join team <ArrowRight size={16} aria-hidden="true" /></button></form></section></div><div class="demo-notice"><ShieldCheck size={18} aria-hidden="true" /><p>All team members can submit predictions. Upload quotas and results are shared by the team.</p></div>{/if}

